-- Classroom Day Lesson Plan Builder + richer Academy Classes topics.
--
-- Two separate things ship in this file, matching the app-side split
-- (see src/screens/LessonBuilder.js and src/components/TopicLessonPanel.js
-- for the "why" — the Classroom Day Builder is intentionally its own
-- surface, not folded into the per-topic Learn/Watch/Practice/Apply
-- content):
--
--   1. teacher_lesson_plans — a normal owner-scoped table (same RLS shape
--      as portfolio_entries) holding a teacher's saved, built lesson
--      plans from the Classroom Day Builder.
--
--   2. app_content additions:
--        a. type='lesson_activity' — the content bank the Builder picks
--           from, one row per pickable item, key = `${subjectSlug}_
--           ${gradeBand}` (e.g. "Math_K-2"; see subjectSlug() in
--           src/data/classCatalog.js), meta.role one of: objective,
--           material, warmup, concept, watch, practice, apply, wrapup,
--           assessment (src/data/lessonPlanTemplates.js#BANK_ROLE_META).
--           Seeded here for all 10 subjects x all 4 grade bands — this is
--           the "way more information" the user will keep adding to
--           directly in Supabase; the app never needs a rebuild for it.
--        b. UPDATEs merging `learn`/`practice`/`apply` into 6 existing
--           class_topic rows (one per built subject) — a worked example
--           of the richer per-topic lesson content TopicLessonPanel.js
--           renders, so there's a concrete pattern to copy when filling
--           in the rest of the ~40 existing topics over time.
--
-- Apply this in the Supabase SQL editor, or via `supabase db push`. Safe
-- to run once; re-running re-inserts duplicate lesson_activity rows (same
-- no-natural-unique-key caveat as every other app_content seed migration
-- in this folder) but the class_topic UPDATEs are idempotent (they merge
-- the same object back onto itself).

-- ── teacher_lesson_plans ─────────────────────────────────────────────────
-- Single-owner data, so ordinary owner-scoped RLS (same pattern as
-- portfolio_entries — see 20260905_portfolio_entries.sql), not the
-- SECURITY DEFINER RPC pattern this project reserves for cross-user access.

create table if not exists public.teacher_lesson_plans (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references public.profiles(id) on delete cascade,
  title         text not null,
  subject_title text not null,
  grade_band    text not null check (grade_band in ('K-2', '3-5', '6-8', '9-12')),
  format        text not null check (format in ('45', '90')),
  objectives    jsonb not null default '[]'::jsonb,   -- string[]
  materials     jsonb not null default '[]'::jsonb,   -- string[]
  assessment    jsonb not null default '[]'::jsonb,   -- string[]
  segments      jsonb not null default '[]'::jsonb,   -- [{key,label,minutes,items:[{title,body}]}]
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create index if not exists teacher_lesson_plans_user_idx
  on public.teacher_lesson_plans (user_id, created_at desc);

alter table public.teacher_lesson_plans enable row level security;

create policy "teacher_lesson_plans_select_own" on public.teacher_lesson_plans
  for select using (auth.uid() = user_id);

create policy "teacher_lesson_plans_insert_own" on public.teacher_lesson_plans
  for insert with check (auth.uid() = user_id);

create policy "teacher_lesson_plans_update_own" on public.teacher_lesson_plans
  for update using (auth.uid() = user_id);

create policy "teacher_lesson_plans_delete_own" on public.teacher_lesson_plans
  for delete using (auth.uid() = user_id);

drop trigger if exists teacher_lesson_plans_touch_updated_at on public.teacher_lesson_plans;
create trigger teacher_lesson_plans_touch_updated_at
  before update on public.teacher_lesson_plans
  for each row execute function public.touch_updated_at();

