  ('lesson_activity', 'Science_6-8', 'Warm-Up', 'Open class by asking students what they already know about ecosystems & food webs, then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"Ecosystems & Food Webs"}'::jsonb, 2),
  ('lesson_activity', 'Science_6-8', 'Food Webs', 'Energy flows through ecosystems: Producers (plants) make energy from sun, Consumers (animals) eat plants/animals, and Decomposers (fungi/bacteria) recycle waste — interconnected chains form a food web.', '{"role":"concept","topic":"Ecosystems & Food Webs"}'::jsonb, 3),
  ('lesson_activity', 'Science_6-8', 'The Serengeti Food Web', 'Timestamp 3:20 — "If an apex predator is removed, herbivore populations explode and strip the plant life."', '{"role":"watch","topic":"Ecosystems & Food Webs"}'::jsonb, 4),
  ('lesson_activity', 'Science_6-8', 'Practice: Name the Role', 'Q: In a pond, algae is eaten by minnows, which are eaten by bass. What role do minnows play?
A: Primary consumer / herbivore.', '{"role":"practice","topic":"Ecosystems & Food Webs"}'::jsonb, 5),
  ('lesson_activity', 'Science_6-8', 'Mini-Project: Draw a Food Chain', 'Draw a 4-organism food chain using local wildlife in your region (e.g., Grass → Grasshopper → Bird → Hawk). Label each role.', '{"role":"apply","topic":"Ecosystems & Food Webs"}'::jsonb, 6),
  ('lesson_activity', 'Science_6-8', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about ecosystems & food webs.', '{"role":"wrapup","topic":"Ecosystems & Food Webs"}'::jsonb, 7),
