  ('lesson_activity', 'Science_9-12', 'Photosynthesis & Respiration', 'Photosynthesis converts light, CO2, and H2O into glucose and O2. Cellular respiration breaks down glucose with O2 to create ATP energy for cells.', '{"role":"concept","topic":"Cellular Respiration vs. Photosynthesis"}'::jsonb, 3),
  ('lesson_activity', 'Science_9-12', 'Mitochondria vs. Chloroplasts', 'Timestamp 4:05 — "Chloroplasts build energy molecules; mitochondria burn them to power cellular work."', '{"role":"watch","topic":"Cellular Respiration vs. Photosynthesis"}'::jsonb, 4),
  ('lesson_activity', 'Science_9-12', 'Practice: Which Organelle?', 'Q: Which organelle generates ATP during cellular respiration?
A: The mitochondrion.', '{"role":"practice","topic":"Cellular Respiration vs. Photosynthesis"}'::jsonb, 5),
  ('lesson_activity', 'Science_9-12', 'Mini-Project: Energy Flow Diagram', 'Create a simple 2-block diagram showing how the chemical outputs of photosynthesis become the inputs for cellular respiration.', '{"role":"apply","topic":"Cellular Respiration vs. Photosynthesis"}'::jsonb, 6),
  ('lesson_activity', 'Science_9-12', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about cellular respiration vs. photosynthesis.', '{"role":"wrapup","topic":"Cellular Respiration vs. Photosynthesis"}'::jsonb, 7),
