  ('lesson_activity', 'SocialSciences_K-2', 'Community Helpers', 'A community is a place where people live, work, and play. Community helpers (firefighters, mail carriers, doctors, teachers) keep communities safe, healthy, and organized.', '{"role":"concept","topic":"Community Helpers & Roles"}'::jsonb, 3),
  ('lesson_activity', 'SocialSciences_K-2', 'A Day in Our Neighborhood', 'Timestamp 1:00 — "Community helpers work together like a team to care for everyone."', '{"role":"watch","topic":"Community Helpers & Roles"}'::jsonb, 4),
  ('lesson_activity', 'SocialSciences_K-2', 'Practice: Who Do You Call?', 'Q: Who would you call if you saw a water pipe leaking on the street?
A: A water utility worker / plumber.', '{"role":"practice","topic":"Community Helpers & Roles"}'::jsonb, 5),
  ('lesson_activity', 'SocialSciences_K-2', 'Mini-Project: Helper Drawing', 'Draw a picture of your favorite community helper and write 1 sentence describing how they help your neighborhood.', '{"role":"apply","topic":"Community Helpers & Roles"}'::jsonb, 6),
