  ('lesson_activity', 'SocialSciences_3-5', 'Warm-Up', 'Open class by asking students what they already know about map skills & cardinal directions, then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"Map Skills & Cardinal Directions"}'::jsonb, 2),
  ('lesson_activity', 'SocialSciences_3-5', 'Reading a Map', 'Maps use cardinal directions: North, South, East, West ("Never Eat Soggy Waffles"). A map key (legend) explains symbols, and a scale shows real-world distance.', '{"role":"concept","topic":"Map Skills & Cardinal Directions"}'::jsonb, 3),
  ('lesson_activity', 'SocialSciences_3-5', 'Reading Maps Like an Explorer', 'Timestamp 1:40 — "Look at the compass rose to find which direction you are traveling."', '{"role":"watch","topic":"Map Skills & Cardinal Directions"}'::jsonb, 4),
  ('lesson_activity', 'SocialSciences_3-5', 'Practice: Which Direction?', 'Q: If you move from the bottom of a map toward the top, which cardinal direction are you traveling?
A: North.', '{"role":"practice","topic":"Map Skills & Cardinal Directions"}'::jsonb, 5),
  ('lesson_activity', 'SocialSciences_3-5', 'Mini-Project: Map Your Room', 'Draw a floor map of your bedroom or living room. Include a compass rose showing North and a map key with at least 3 symbols.', '{"role":"apply","topic":"Map Skills & Cardinal Directions"}'::jsonb, 6),
