  ('lesson_activity', 'SocialSciences_6-8', 'Warm-Up', 'Open class by asking students what they already know about ancient civilizations & geography, then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"Ancient Civilizations & Geography"}'::jsonb, 2),
  ('lesson_activity', 'SocialSciences_6-8', 'River Valley Civilizations', 'Early civilizations (Mesopotamia, Egypt, Indus Valley) developed along major rivers. River valleys provided fertile soil, fresh water, and transportation routes.', '{"role":"concept","topic":"Ancient Civilizations & Geography"}'::jsonb, 3),
  ('lesson_activity', 'SocialSciences_6-8', 'Why Civilizations Started in River Valleys', 'Timestamp 2:30 — "Annual river flooding deposited rich silt, allowing early humans to farm and build permanent cities."', '{"role":"watch","topic":"Ancient Civilizations & Geography"}'::jsonb, 4),
  ('lesson_activity', 'SocialSciences_6-8', 'Practice: Why the Nile?', 'Q: Why was the Nile River essential to ancient Egyptian civilization?
A: It provided fertile soil for farming and a trade highway through the desert.', '{"role":"practice","topic":"Ancient Civilizations & Geography"}'::jsonb, 5),
  ('lesson_activity', 'SocialSciences_6-8', 'Mini-Project: Modern River Valleys', 'Find a world map. Identify 2 modern countries along historical river valleys and list 1 natural advantage that location still provides today.', '{"role":"apply","topic":"Ancient Civilizations & Geography"}'::jsonb, 6),
  ('lesson_activity', 'SocialSciences_6-8', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about ancient civilizations & geography.', '{"role":"wrapup","topic":"Ancient Civilizations & Geography"}'::jsonb, 7),
