  ('lesson_activity', 'SocialSciences_9-12', 'Materials Needed', 'Paper, pencil, and whatever the Apply challenge below calls for (a household item, a device, or internet access).', '{"role":"material","topic":"Supply, Demand & Market Equilibrium"}'::jsonb, 1),
  ('lesson_activity', 'SocialSciences_9-12', 'Warm-Up', 'Open class by asking students what they already know about supply, demand & market equilibrium, then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"Supply, Demand & Market Equilibrium"}'::jsonb, 2),
  ('lesson_activity', 'SocialSciences_9-12', 'Market Equilibrium', 'Demand slopes down (higher price = lower demand). Supply slopes up (higher price = higher supply). Equilibrium is where quantity supplied equals quantity demanded.', '{"role":"concept","topic":"Supply, Demand & Market Equilibrium"}'::jsonb, 3),
  ('lesson_activity', 'SocialSciences_9-12', 'Market Forces & Price Signals', 'Timestamp 2:40 — "When demand shifts right due to a trend, prices rise until supply catches up."', '{"role":"watch","topic":"Supply, Demand & Market Equilibrium"}'::jsonb, 4),
  ('lesson_activity', 'SocialSciences_9-12', 'Practice: Ticket Demand', 'Q: If concert ticket demand doubles overnight but venue capacity stays fixed, what happens to equilibrium price?
A: It increases.', '{"role":"practice","topic":"Supply, Demand & Market Equilibrium"}'::jsonb, 5),
  ('lesson_activity', 'SocialSciences_9-12', 'Mini-Project: Shift the Supply Curve', 'Choose a product you bought recently. Describe one event that would shift its supply curve left and predict the impact on retail pricing.', '{"role":"apply","topic":"Supply, Demand & Market Equilibrium"}'::jsonb, 6),
  ('lesson_activity', 'SocialSciences_9-12', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about supply, demand & market equilibrium.', '{"role":"wrapup","topic":"Supply, Demand & Market Equilibrium"}'::jsonb, 7),
