  ('lesson_activity', 'ArtMusic_K-2', 'Primary & Secondary Colors', 'Primary colors are Red, Yellow, and Blue — you cannot make them by mixing others. Mixing two primary colors creates Secondary colors (Orange, Green, Purple).', '{"role":"concept","topic":"Primary Colors & Mixing"}'::jsonb, 3),
  ('lesson_activity', 'ArtMusic_K-2', 'The Magic Color Mixer', 'Timestamp 0:45 — "Watch what happens when yellow and blue swirl together!"', '{"role":"watch","topic":"Primary Colors & Mixing"}'::jsonb, 4),
  ('lesson_activity', 'ArtMusic_K-2', 'Practice: Mix a Color', 'Q: What color do you get when you mix Red and Yellow?
A: Orange.', '{"role":"practice","topic":"Primary Colors & Mixing"}'::jsonb, 5),
  ('lesson_activity', 'ArtMusic_K-2', 'Mini-Project: Mix & Photograph', 'Use crayons, markers, or paints to mix two primary colors together. Take a photo of the new secondary color you created.', '{"role":"apply","topic":"Primary Colors & Mixing"}'::jsonb, 6),
  ('lesson_activity', 'ArtMusic_K-2', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about primary colors & mixing.', '{"role":"wrapup","topic":"Primary Colors & Mixing"}'::jsonb, 7),
