  ('lesson_activity', 'ArtMusic_3-5', 'Warm-Up', 'Open class by asking students what they already know about rhythm & basic musical notation, then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"Rhythm & Basic Musical Notation"}'::jsonb, 2),
  ('lesson_activity', 'ArtMusic_3-5', 'Beats & Notes', 'Music is measured in beats: Whole Note = 4 beats, Half Note = 2 beats, Quarter Note = 1 beat, Eighth Note = 1/2 beat.', '{"role":"concept","topic":"Rhythm & Basic Musical Notation"}'::jsonb, 3),
  ('lesson_activity', 'ArtMusic_3-5', 'Clapping the Beat', 'Timestamp 1:20 — "Count along out loud: 1-2-3-4 for every whole note measure."', '{"role":"watch","topic":"Rhythm & Basic Musical Notation"}'::jsonb, 4),
  ('lesson_activity', 'ArtMusic_3-5', 'Practice: Note Values', 'Q: How many quarter notes equal the duration of one whole note?
A: 4.', '{"role":"practice","topic":"Rhythm & Basic Musical Notation"}'::jsonb, 5),
  ('lesson_activity', 'ArtMusic_3-5', 'Mini-Project: Clap a Rhythm', 'Create a 4-beat rhythm using quarter notes and half notes. Record a 5-second clip clapping your rhythm while counting the beats out loud.', '{"role":"apply","topic":"Rhythm & Basic Musical Notation"}'::jsonb, 6),
  ('lesson_activity', 'ArtMusic_3-5', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about rhythm & basic musical notation.', '{"role":"wrapup","topic":"Rhythm & Basic Musical Notation"}'::jsonb, 7),
