  ('lesson_activity', 'ArtMusic_6-8', 'Warm-Up', 'Open class by asking students what they already know about perspective & depth in drawing, then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"Perspective & Depth in Drawing"}'::jsonb, 2),
  ('lesson_activity', 'ArtMusic_6-8', 'One-Point Perspective', 'One-point perspective uses a horizon line and a single vanishing point where parallel lines converge — creating the illusion of 3D depth on a flat page.', '{"role":"concept","topic":"Perspective & Depth in Drawing"}'::jsonb, 3),
  ('lesson_activity', 'ArtMusic_6-8', 'Drawing Roadways in Perspective', 'Timestamp 2:15 — "Notice how objects get smaller and move closer together as they approach the vanishing point."', '{"role":"watch","topic":"Perspective & Depth in Drawing"}'::jsonb, 4),
  ('lesson_activity', 'ArtMusic_6-8', 'Practice: Where Do Lines Meet?', 'Q: Where do parallel lines appear to meet in a perspective drawing?
A: At the vanishing point.', '{"role":"practice","topic":"Perspective & Depth in Drawing"}'::jsonb, 5),
  ('lesson_activity', 'ArtMusic_6-8', 'Mini-Project: Draw a Vanishing Road', 'Using a ruler and pencil, draw a straight road or hallway that tapers into a single vanishing point on a horizon line.', '{"role":"apply","topic":"Perspective & Depth in Drawing"}'::jsonb, 6),
  ('lesson_activity', 'ArtMusic_6-8', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about perspective & depth in drawing.', '{"role":"wrapup","topic":"Perspective & Depth in Drawing"}'::jsonb, 7),
