  ('lesson_activity', 'ArtMusic_9-12', 'Warm-Up', 'Open class by asking students what they already know about color theory & high-contrast composition, then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"Color Theory & High-Contrast Composition"}'::jsonb, 2),
  ('lesson_activity', 'ArtMusic_9-12', 'Complementary Colors', 'Complementary colors sit opposite each other on the color wheel (blue/orange, red/green, yellow/purple). Placing them side-by-side creates strong visual contrast.', '{"role":"concept","topic":"Color Theory & High-Contrast Composition"}'::jsonb, 3),
  ('lesson_activity', 'ArtMusic_9-12', 'Color Schemes in Cinema & Graphic Design', 'Timestamp 1:15 — "Observe how movie posters use teal and orange to separate characters from backgrounds."', '{"role":"watch","topic":"Color Theory & High-Contrast Composition"}'::jsonb, 4),
  ('lesson_activity', 'ArtMusic_9-12', 'Practice: Find the Complement', 'Q: What is the complementary color of yellow?
A: Purple.', '{"role":"practice","topic":"Color Theory & High-Contrast Composition"}'::jsonb, 5),
  ('lesson_activity', 'ArtMusic_9-12', 'Mini-Project: High-Contrast Icon', 'Design a simple high-contrast icon using only two complementary colors, or photograph a real scene showing complementary contrast.', '{"role":"apply","topic":"Color Theory & High-Contrast Composition"}'::jsonb, 6),
  ('lesson_activity', 'ArtMusic_9-12', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about color theory & high-contrast composition.', '{"role":"wrapup","topic":"Color Theory & High-Contrast Composition"}'::jsonb, 7),
