  ('lesson_activity', 'HomeEconomicsWorkshop_K-2', 'Warm-Up', 'Open class by asking students what they already know about sorting, folding & tidy spaces, then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"Sorting, Folding & Tidy Spaces"}'::jsonb, 2),
  ('lesson_activity', 'HomeEconomicsWorkshop_K-2', 'Sorting & Folding', 'Keeping things organized makes spaces safer and easier to use. Sorting means grouping things that are alike (shirts with shirts, socks with socks).', '{"role":"concept","topic":"Sorting, Folding & Tidy Spaces"}'::jsonb, 3),
  ('lesson_activity', 'HomeEconomicsWorkshop_K-2', 'The Folding Song', 'Timestamp 0:50 — "Watch how we lay the shirt flat, tuck the sleeves, and fold it in half."', '{"role":"watch","topic":"Sorting, Folding & Tidy Spaces"}'::jsonb, 4),
  ('lesson_activity', 'HomeEconomicsWorkshop_K-2', 'Practice: Sock Pairs', 'Q: If you have 3 red socks and 3 blue socks mixed in a basket, how many matched pairs can you make?
A: 3 pairs.', '{"role":"practice","topic":"Sorting, Folding & Tidy Spaces"}'::jsonb, 5),
  ('lesson_activity', 'HomeEconomicsWorkshop_K-2', 'Mini-Project: Fold & Stack', 'Practice folding 3 shirts or towels neatly and place them in a stack. Take a photo of your stack.', '{"role":"apply","topic":"Sorting, Folding & Tidy Spaces"}'::jsonb, 6),
