  ('lesson_activity', 'HomeEconomicsWorkshop_3-5', 'Materials Needed', 'Paper, pencil, and whatever the Apply challenge below calls for (a household item, a device, or internet access).', '{"role":"material","topic":"Basic Kitchen Safety & Measuring Ingredients"}'::jsonb, 1),
  ('lesson_activity', 'HomeEconomicsWorkshop_3-5', 'Warm-Up', 'Open class by asking students what they already know about basic kitchen safety & measuring ingredients, then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"Basic Kitchen Safety & Measuring Ingredients"}'::jsonb, 2),
  ('lesson_activity', 'HomeEconomicsWorkshop_3-5', 'Measuring Safely', 'Cooking safely means washing hands first, turning pot handles inward, and using exact measurements. Liquid measures use clear cups with lines; dry measures get leveled off flat.', '{"role":"concept","topic":"Basic Kitchen Safety & Measuring Ingredients"}'::jsonb, 3),
  ('lesson_activity', 'HomeEconomicsWorkshop_3-5', 'Measuring Like a Chef', 'Timestamp 1:30 — "Level off flour with the flat side of a knife so you don''t pack in too much."', '{"role":"watch","topic":"Basic Kitchen Safety & Measuring Ingredients"}'::jsonb, 4),
  ('lesson_activity', 'HomeEconomicsWorkshop_3-5', 'Practice: Which Cup?', 'Q: Which tool should you use to measure 1/2 cup of milk?
A: A clear liquid measuring cup.', '{"role":"practice","topic":"Basic Kitchen Safety & Measuring Ingredients"}'::jsonb, 5),
  ('lesson_activity', 'HomeEconomicsWorkshop_3-5', 'Mini-Project: Measure & Photograph', 'Find a measuring cup or spoon at home. Measure 1 cup of water and pour it into a clear glass, photographing your measurement at eye level.', '{"role":"apply","topic":"Basic Kitchen Safety & Measuring Ingredients"}'::jsonb, 6),
  ('lesson_activity', 'HomeEconomicsWorkshop_3-5', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about basic kitchen safety & measuring ingredients.', '{"role":"wrapup","topic":"Basic Kitchen Safety & Measuring Ingredients"}'::jsonb, 7),
  ('lesson_activity', 'HomeEconomicsWorkshop_3-5', 'Assessment', 'Can the student answer the Practice question correctly and complete the Apply challenge as described?', '{"role":"assessment","topic":"Basic Kitchen Safety & Measuring Ingredients"}'::jsonb, 8),
  ('lesson_activity', 'HomeEconomicsWorkshop_6-8', 'Lesson Objective', 'Students will be able to explain and apply the core idea behind "Hand Sewing & Fabric Repair."', '{"role":"objective","topic":"Hand Sewing & Fabric Repair"}'::jsonb, 0),
  ('lesson_activity', 'HomeEconomicsWorkshop_6-8', 'Materials Needed', 'Paper, pencil, and whatever the Apply challenge below calls for (a household item, a device, or internet access).', '{"role":"material","topic":"Hand Sewing & Fabric Repair"}'::jsonb, 1),
  ('lesson_activity', 'HomeEconomicsWorkshop_6-8', 'Warm-Up', 'Open class by asking students what they already know about hand sewing & fabric repair, then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"Hand Sewing & Fabric Repair"}'::jsonb, 2),
  ('lesson_activity', 'HomeEconomicsWorkshop_6-8', 'The Running Stitch', 'Hand sewing uses a needle and thread to repair clothing. Threading the needle, tying a secure end-knot, and using a running stitch (in-and-out) lets you mend loose seams or attach buttons.', '{"role":"concept","topic":"Hand Sewing & Fabric Repair"}'::jsonb, 3),
  ('lesson_activity', 'HomeEconomicsWorkshop_6-8', 'Fixing a Loose Button in 3 Minutes', 'Timestamp 1:10 — "Make an X stitch pattern through the button holes to hold it tight."', '{"role":"watch","topic":"Hand Sewing & Fabric Repair"}'::jsonb, 4),
  ('lesson_activity', 'HomeEconomicsWorkshop_6-8', 'Practice: Name the Stitch', 'Q: What stitch goes up through the fabric and down a short distance away in a straight line?
A: Running stitch.', '{"role":"practice","topic":"Hand Sewing & Fabric Repair"}'::jsonb, 5),
  ('lesson_activity', 'HomeEconomicsWorkshop_6-8', 'Mini-Project: Practice Stitching', 'Practice a running stitch on a scrap of cloth or paper using a needle and thread (or lacing string through punched paper holes) for 5 stitches.', '{"role":"apply","topic":"Hand Sewing & Fabric Repair"}'::jsonb, 6),
  ('lesson_activity', 'HomeEconomicsWorkshop_6-8', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about hand sewing & fabric repair.', '{"role":"wrapup","topic":"Hand Sewing & Fabric Repair"}'::jsonb, 7),
  ('lesson_activity', 'HomeEconomicsWorkshop_6-8', 'Assessment', 'Can the student answer the Practice question correctly and complete the Apply challenge as described?', '{"role":"assessment","topic":"Hand Sewing & Fabric Repair"}'::jsonb, 8),
  ('lesson_activity', 'HomeEconomicsWorkshop_9-12', 'Lesson Objective', 'Students will be able to explain and apply the core idea behind "Circuitry, Diagnostics & Appliance Safety."', '{"role":"objective","topic":"Circuitry, Diagnostics & Appliance Safety"}'::jsonb, 0),
  ('lesson_activity', 'HomeEconomicsWorkshop_9-12', 'Materials Needed', 'Paper, pencil, and whatever the Apply challenge below calls for (a household item, a device, or internet access).', '{"role":"material","topic":"Circuitry, Diagnostics & Appliance Safety"}'::jsonb, 1),
  ('lesson_activity', 'HomeEconomicsWorkshop_9-12', 'Warm-Up', 'Open class by asking students what they already know about circuitry, diagnostics & appliance safety, then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"Circuitry, Diagnostics & Appliance Safety"}'::jsonb, 2),
  ('lesson_activity', 'HomeEconomicsWorkshop_9-12', 'Voltage, Current & Resistance', 'Electrical current flows in a closed loop. Voltage (V) is pressure, Current (I) is flow, and Resistance (R) opposes flow (V = I × R). Always isolate power before diagnosing hardware.', '{"role":"concept","topic":"Circuitry, Diagnostics & Appliance Safety"}'::jsonb, 3),
  ('lesson_activity', 'HomeEconomicsWorkshop_9-12', 'Using a Multimeter Safely', 'Timestamp 0:45 — "Set your multimeter to test continuity before checking for broken wire paths."', '{"role":"watch","topic":"Circuitry, Diagnostics & Appliance Safety"}'::jsonb, 4),
  ('lesson_activity', 'HomeEconomicsWorkshop_9-12', 'Practice: Open Circuit', 'Q: If resistance in a circuit goes to infinity, what has occurred?
A: An open circuit / break in the loop.', '{"role":"practice","topic":"Circuitry, Diagnostics & Appliance Safety"}'::jsonb, 5),
  ('lesson_activity', 'HomeEconomicsWorkshop_9-12', 'Mini-Project: Cable Safety Check', 'Inspect an unplugged device cable in your house. Check for wire strain, jacket fraying, or loose pins, and record your findings on a safety checklist.', '{"role":"apply","topic":"Circuitry, Diagnostics & Appliance Safety"}'::jsonb, 6),
  ('lesson_activity', 'HomeEconomicsWorkshop_9-12', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about circuitry, diagnostics & appliance safety.', '{"role":"wrapup","topic":"Circuitry, Diagnostics & Appliance Safety"}'::jsonb, 7),
  ('lesson_activity', 'HomeEconomicsWorkshop_9-12', 'Assessment', 'Can the student answer the Practice question correctly and complete the Apply challenge as described?', '{"role":"assessment","topic":"Circuitry, Diagnostics & Appliance Safety"}'::jsonb, 8),
  ('lesson_activity', 'TechnologyEngineering_K-2', 'Lesson Objective', 'Students will be able to explain and apply the core idea behind "Algorithms & Sequencing."', '{"role":"objective","topic":"Algorithms & Sequencing"}'::jsonb, 0),
  ('lesson_activity', 'TechnologyEngineering_K-2', 'Materials Needed', 'Paper, pencil, and whatever the Apply challenge below calls for (a household item, a device, or internet access).', '{"role":"material","topic":"Algorithms & Sequencing"}'::jsonb, 1),
  ('lesson_activity', 'TechnologyEngineering_K-2', 'Warm-Up', 'Open class by asking students what they already know about algorithms & sequencing, then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"Algorithms & Sequencing"}'::jsonb, 2),
  ('lesson_activity', 'TechnologyEngineering_K-2', 'Step-by-Step Instructions', 'An algorithm is a step-by-step set of instructions to finish a task. Computers need instructions in the exact right order, just like following steps to brush your teeth.', '{"role":"concept","topic":"Algorithms & Sequencing"}'::jsonb, 3),
  ('lesson_activity', 'TechnologyEngineering_K-2', 'Robot Sandwich Maker', 'Timestamp 1:05 — "If you don''t tell the robot to open the bread bag first, it puts butter on the outside of the plastic!"', '{"role":"watch","topic":"Algorithms & Sequencing"}'::jsonb, 4),
  ('lesson_activity', 'TechnologyEngineering_K-2', 'Practice: Put It in Order', 'Q: Put these steps in order to put on shoes: 1) Tie laces, 2) Put on socks, 3) Slip feet into shoes.
A: 2, 3, 1.', '{"role":"practice","topic":"Algorithms & Sequencing"}'::jsonb, 5),
  ('lesson_activity', 'TechnologyEngineering_K-2', 'Mini-Project: Write an Algorithm', 'Write or draw a 4-step algorithm telling a friend how to make a paper airplane or draw a smiley face.', '{"role":"apply","topic":"Algorithms & Sequencing"}'::jsonb, 6),
  ('lesson_activity', 'TechnologyEngineering_K-2', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about algorithms & sequencing.', '{"role":"wrapup","topic":"Algorithms & Sequencing"}'::jsonb, 7),
  ('lesson_activity', 'TechnologyEngineering_K-2', 'Assessment', 'Can the student answer the Practice question correctly and complete the Apply challenge as described?', '{"role":"assessment","topic":"Algorithms & Sequencing"}'::jsonb, 8),
  ('lesson_activity', 'TechnologyEngineering_3-5', 'Lesson Objective', 'Students will be able to explain and apply the core idea behind "Block-Based Coding & Loops."', '{"role":"objective","topic":"Block-Based Coding & Loops"}'::jsonb, 0),
  ('lesson_activity', 'TechnologyEngineering_3-5', 'Materials Needed', 'Paper, pencil, and whatever the Apply challenge below calls for (a household item, a device, or internet access).', '{"role":"material","topic":"Block-Based Coding & Loops"}'::jsonb, 1),
  ('lesson_activity', 'TechnologyEngineering_3-5', 'Warm-Up', 'Open class by asking students what they already know about block-based coding & loops, then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"Block-Based Coding & Loops"}'::jsonb, 2),
  ('lesson_activity', 'TechnologyEngineering_3-5', 'Loops', 'A loop repeats a set of instructions multiple times so you don''t have to write the same line over and over.', '{"role":"concept","topic":"Block-Based Coding & Loops"}'::jsonb, 3),
  ('lesson_activity', 'TechnologyEngineering_3-5', 'Coding Loops in Scratch', 'Timestamp 1:40 — "Instead of writing ''Move Forward'' 10 times, place 1 ''Move Forward'' block inside a ''Repeat 10'' loop."', '{"role":"watch","topic":"Block-Based Coding & Loops"}'::jsonb, 4),
  ('lesson_activity', 'TechnologyEngineering_3-5', 'Practice: What Happens?', 'Q: If a block inside a "Repeat 4 Times" loop says "Turn Right 90 Degrees," what shape path will your character move in?
A: A full circle back to its starting orientation.', '{"role":"practice","topic":"Block-Based Coding & Loops"}'::jsonb, 5),
  ('lesson_activity', 'TechnologyEngineering_3-5', 'Mini-Project: Write a Loop Routine', 'Write a short block-style pseudo-code routine that makes a character walk forward 3 steps, jump, and repeat that sequence 3 times.', '{"role":"apply","topic":"Block-Based Coding & Loops"}'::jsonb, 6),
  ('lesson_activity', 'TechnologyEngineering_3-5', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about block-based coding & loops.', '{"role":"wrapup","topic":"Block-Based Coding & Loops"}'::jsonb, 7),
