  ('lesson_activity', 'TechnologyEngineering_6-8', 'Lesson Objective', 'Students will be able to explain and apply the core idea behind "3D Modeling & CAD Fundamentals."', '{"role":"objective","topic":"3D Modeling & CAD Fundamentals"}'::jsonb, 0),
  ('lesson_activity', 'TechnologyEngineering_6-8', 'Materials Needed', 'Paper, pencil, and whatever the Apply challenge below calls for (a household item, a device, or internet access).', '{"role":"material","topic":"3D Modeling & CAD Fundamentals"}'::jsonb, 1),
  ('lesson_activity', 'TechnologyEngineering_6-8', 'Warm-Up', 'Open class by asking students what they already know about 3d modeling & cad fundamentals, then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"3D Modeling & CAD Fundamentals"}'::jsonb, 2),
  ('lesson_activity', 'TechnologyEngineering_6-8', 'Additive & Subtractive Modeling', 'CAD builds 3D digital objects using primitive shapes (cubes, cylinders, spheres). You combine shapes using additive (joining parts) and subtractive (cutting holes) modeling.', '{"role":"concept","topic":"3D Modeling & CAD Fundamentals"}'::jsonb, 3),
  ('lesson_activity', 'TechnologyEngineering_6-8', 'Intro to Tinkercad Basics', 'Timestamp 2:10 — "Group a solid cylinder with a hole-cylinder to turn a solid block into a pipe."', '{"role":"watch","topic":"3D Modeling & CAD Fundamentals"}'::jsonb, 4),
  ('lesson_activity', 'TechnologyEngineering_6-8', 'Practice: Name the Technique', 'Q: What modeling technique removes volume from an object to create a window or socket?
A: Subtractive modeling / hole grouping.', '{"role":"practice","topic":"3D Modeling & CAD Fundamentals"}'::jsonb, 5),
  ('lesson_activity', 'TechnologyEngineering_6-8', 'Mini-Project: Sketch a CAD Build', 'Sketch a 3D object (like a mug or pencil holder) on paper and break down which primitive shapes you would combine to build it in CAD.', '{"role":"apply","topic":"3D Modeling & CAD Fundamentals"}'::jsonb, 6),
  ('lesson_activity', 'TechnologyEngineering_6-8', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about 3d modeling & cad fundamentals.', '{"role":"wrapup","topic":"3D Modeling & CAD Fundamentals"}'::jsonb, 7),
