  ('lesson_activity', 'TechnologyEngineering_9-12', 'Warm-Up', 'Open class by asking students what they already know about restful apis & web communication, then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"RESTful APIs & Web Communication"}'::jsonb, 2),
  ('lesson_activity', 'TechnologyEngineering_9-12', 'HTTP Verbs', 'APIs let software applications communicate. REST uses standard HTTP verbs — GET fetches data, POST creates new data, PUT/PATCH updates data, DELETE removes data.', '{"role":"concept","topic":"RESTful APIs & Web Communication"}'::jsonb, 3),
  ('lesson_activity', 'TechnologyEngineering_9-12', 'How Web Services Talk', 'Timestamp 3:20 — "HTTP status code 200 OK means your request succeeded and returned data."', '{"role":"watch","topic":"RESTful APIs & Web Communication"}'::jsonb, 4),
  ('lesson_activity', 'TechnologyEngineering_9-12', 'Practice: Which Method?', 'Q: Which HTTP method should a client send when submitting a new user registration form?
A: POST.', '{"role":"practice","topic":"RESTful APIs & Web Communication"}'::jsonb, 5),
  ('lesson_activity', 'TechnologyEngineering_9-12', 'Mini-Project: Call a Public API', 'Use a browser dev console or a tool like Postman to send a GET request to a public API (e.g. api.github.com/users/octocat) and copy the JSON field containing the account name.', '{"role":"apply","topic":"RESTful APIs & Web Communication"}'::jsonb, 6),
  ('lesson_activity', 'TechnologyEngineering_9-12', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about restful apis & web communication.', '{"role":"wrapup","topic":"RESTful APIs & Web Communication"}'::jsonb, 7),
