  ('lesson_activity', 'ForeignLanguage_K-2', 'Materials Needed', 'Paper, pencil, and whatever the Apply challenge below calls for (a household item, a device, or internet access).', '{"role":"material","topic":"Greetings, Feelings & Manners (Spanish)"}'::jsonb, 1),
  ('lesson_activity', 'ForeignLanguage_K-2', 'Warm-Up', 'Open class by asking students what they already know about greetings, feelings & manners (spanish), then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"Greetings, Feelings & Manners (Spanish)"}'::jsonb, 2),
  ('lesson_activity', 'ForeignLanguage_K-2', 'Greetings & Manners', '"¡Hola!" = Hello! "¿Cómo estás?" = How are you? "Estoy bien / feliz." = I am good / happy. "Gracias" = Thank you.', '{"role":"concept","topic":"Greetings, Feelings & Manners (Spanish)"}'::jsonb, 3),
  ('lesson_activity', 'ForeignLanguage_K-2', 'Sing Along Spanish Greetings', 'Timestamp 0:40 — "Practice saying ¡Buenos días! when the sun comes up."', '{"role":"watch","topic":"Greetings, Feelings & Manners (Spanish)"}'::jsonb, 4),
  ('lesson_activity', 'ForeignLanguage_K-2', 'Practice: Say Thank You', 'Q: How do you say "Thank you" in Spanish — Por favor, Gracias, or Hola?
A: Gracias.', '{"role":"practice","topic":"Greetings, Feelings & Manners (Spanish)"}'::jsonb, 5),
  ('lesson_activity', 'ForeignLanguage_K-2', 'Mini-Project: Record a Greeting', 'Record a 5-second voice note greeting someone in Spanish, asking how they are, and saying goodbye ("¡Hola! ¿Cómo estás? ¡Adiós!").', '{"role":"apply","topic":"Greetings, Feelings & Manners (Spanish)"}'::jsonb, 6),
  ('lesson_activity', 'ForeignLanguage_K-2', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about greetings, feelings & manners (spanish).', '{"role":"wrapup","topic":"Greetings, Feelings & Manners (Spanish)"}'::jsonb, 7),
