  ('lesson_activity', 'ForeignLanguage_3-5', 'Materials Needed', 'Paper, pencil, and whatever the Apply challenge below calls for (a household item, a device, or internet access).', '{"role":"material","topic":"Colors, Numbers & Family Words (Spanish)"}'::jsonb, 1),
  ('lesson_activity', 'ForeignLanguage_3-5', 'Warm-Up', 'Open class by asking students what they already know about colors, numbers & family words (spanish), then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"Colors, Numbers & Family Words (Spanish)"}'::jsonb, 2),
  ('lesson_activity', 'ForeignLanguage_3-5', 'Colors, Numbers & Family', 'Numbers: uno, dos, tres, cuatro, cinco. Colors: rojo, azul, verde, amarillo. Family: madre, padre, hermano/a. Adjectives like colors often come after the noun in Spanish.', '{"role":"concept","topic":"Colors, Numbers & Family Words (Spanish)"}'::jsonb, 3),
  ('lesson_activity', 'ForeignLanguage_3-5', 'My Family & Favorite Things', 'Timestamp 1:15 — "Notice how ''el carro rojo'' puts the color word after the noun."', '{"role":"watch","topic":"Colors, Numbers & Family Words (Spanish)"}'::jsonb, 4),
  ('lesson_activity', 'ForeignLanguage_3-5', 'Practice: Translate', 'Q: Translate into English: "Tengo un hermano."
A: "I have one brother."', '{"role":"practice","topic":"Colors, Numbers & Family Words (Spanish)"}'::jsonb, 5),
  ('lesson_activity', 'ForeignLanguage_3-5', 'Mini-Project: Name the Colors', 'Point to 3 colored items in your room and say their color out loud in Spanish while recording a short clip.', '{"role":"apply","topic":"Colors, Numbers & Family Words (Spanish)"}'::jsonb, 6),
  ('lesson_activity', 'ForeignLanguage_3-5', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about colors, numbers & family words (spanish).', '{"role":"wrapup","topic":"Colors, Numbers & Family Words (Spanish)"}'::jsonb, 7),
