  ('lesson_activity', 'ForeignLanguage_6-8', 'Lesson Objective', 'Students will be able to explain and apply the core idea behind "Descriptive Sentences & Daily Routines (Spanish)."', '{"role":"objective","topic":"Descriptive Sentences & Daily Routines (Spanish)"}'::jsonb, 0),
  ('lesson_activity', 'ForeignLanguage_6-8', 'Materials Needed', 'Paper, pencil, and whatever the Apply challenge below calls for (a household item, a device, or internet access).', '{"role":"material","topic":"Descriptive Sentences & Daily Routines (Spanish)"}'::jsonb, 1),
  ('lesson_activity', 'ForeignLanguage_6-8', 'Warm-Up', 'Open class by asking students what they already know about descriptive sentences & daily routines (spanish), then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"Descriptive Sentences & Daily Routines (Spanish)"}'::jsonb, 2),
  ('lesson_activity', 'ForeignLanguage_6-8', 'Conjugating -AR Verbs', 'Regular verbs end in -ar, -er, or -ir. Conjugating changes the ending based on who is doing the action (hablar → yo hablo, tú hablas, él/ella habla).', '{"role":"concept","topic":"Descriptive Sentences & Daily Routines (Spanish)"}'::jsonb, 3),
  ('lesson_activity', 'ForeignLanguage_6-8', 'Conjugating -AR Verbs', 'Timestamp 2:00 — "Drop the -ar and add -o for ''yo'', -as for ''tú'', and -a for ''él/ella''."', '{"role":"watch","topic":"Descriptive Sentences & Daily Routines (Spanish)"}'::jsonb, 4),
  ('lesson_activity', 'ForeignLanguage_6-8', 'Practice: Conjugate It', 'Q: What is the correct form of necesitar (to need) for "I need"?
A: Yo necesito.', '{"role":"practice","topic":"Descriptive Sentences & Daily Routines (Spanish)"}'::jsonb, 5),
  ('lesson_activity', 'ForeignLanguage_6-8', 'Mini-Project: Describe Your Day', 'Write 3 sentences in Spanish describing your daily schedule using common verbs (estudiar, comer, escuchar).', '{"role":"apply","topic":"Descriptive Sentences & Daily Routines (Spanish)"}'::jsonb, 6),
  ('lesson_activity', 'ForeignLanguage_6-8', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about descriptive sentences & daily routines (spanish).', '{"role":"wrapup","topic":"Descriptive Sentences & Daily Routines (Spanish)"}'::jsonb, 7),
