  ('lesson_activity', 'ForeignLanguage_9-12', 'Lesson Objective', 'Students will be able to explain and apply the core idea behind "Ordering Food & Polite Requests (Spanish)."', '{"role":"objective","topic":"Ordering Food & Polite Requests (Spanish)"}'::jsonb, 0),
  ('lesson_activity', 'ForeignLanguage_9-12', 'Materials Needed', 'Paper, pencil, and whatever the Apply challenge below calls for (a household item, a device, or internet access).', '{"role":"material","topic":"Ordering Food & Polite Requests (Spanish)"}'::jsonb, 1),
  ('lesson_activity', 'ForeignLanguage_9-12', 'Warm-Up', 'Open class by asking students what they already know about ordering food & polite requests (spanish), then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"Ordering Food & Polite Requests (Spanish)"}'::jsonb, 2),
  ('lesson_activity', 'ForeignLanguage_9-12', 'Polite Requests', '"Quisiera..." = I would like... "¿Me trae...?" = Could you bring me...? "La cuenta, por favor." = The bill, please. Use formal (usted) forms with waitstaff or strangers.', '{"role":"concept","topic":"Ordering Food & Polite Requests (Spanish)"}'::jsonb, 3),
  ('lesson_activity', 'ForeignLanguage_9-12', 'Conversational Spanish at a Restaurant', 'Timestamp 1:50 — "Listen to native speakers order meals using conditional polite forms."', '{"role":"watch","topic":"Ordering Food & Polite Requests (Spanish)"}'::jsonb, 4),
  ('lesson_activity', 'ForeignLanguage_9-12', 'Practice: Translate a Request', 'Q: Translate to Spanish: "I would like a water, please."
A: "Quisiera un agua, por favor."', '{"role":"practice","topic":"Ordering Food & Polite Requests (Spanish)"}'::jsonb, 5),
  ('lesson_activity', 'ForeignLanguage_9-12', 'Mini-Project: Order a Meal', 'Record a 15-second audio snippet simulating ordering a full meal (one drink, one main dish, and asking for the check) in Spanish.', '{"role":"apply","topic":"Ordering Food & Polite Requests (Spanish)"}'::jsonb, 6),
  ('lesson_activity', 'ForeignLanguage_9-12', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about ordering food & polite requests (spanish).', '{"role":"wrapup","topic":"Ordering Food & Polite Requests (Spanish)"}'::jsonb, 7),
