  ('lesson_activity', 'HealthFitness_K-2', 'Materials Needed', 'Paper, pencil, and whatever the Apply challenge below calls for (a household item, a device, or internet access).', '{"role":"material","topic":"Handwashing & Hygiene Habits"}'::jsonb, 1),
  ('lesson_activity', 'HealthFitness_K-2', 'Warm-Up', 'Open class by asking students what they already know about handwashing & hygiene habits, then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"Handwashing & Hygiene Habits"}'::jsonb, 2),
  ('lesson_activity', 'HealthFitness_K-2', 'Washing Away Germs', 'Germs are tiny living things that can make you sick. Scrubbing hands with soap and warm water for 20 seconds (the time it takes to sing "Happy Birthday" twice) removes germs.', '{"role":"concept","topic":"Handwashing & Hygiene Habits"}'::jsonb, 3),
  ('lesson_activity', 'HealthFitness_K-2', 'The Germ Buster Dance', 'Timestamp 0:45 — "Don''t forget to scrub between your fingers and under your nails!"', '{"role":"watch","topic":"Handwashing & Hygiene Habits"}'::jsonb, 4),
  ('lesson_activity', 'HealthFitness_K-2', 'Practice: How Long?', 'Q: How long should you wash your hands with soap and water — 5 seconds, 20 seconds, or 2 minutes?
A: 20 seconds.', '{"role":"practice","topic":"Handwashing & Hygiene Habits"}'::jsonb, 5),
  ('lesson_activity', 'HealthFitness_K-2', 'Mini-Project: Handwashing Practice', 'Wash your hands properly while singing a 20-second song, and check off a hygiene tracking sheet.', '{"role":"apply","topic":"Handwashing & Hygiene Habits"}'::jsonb, 6),
  ('lesson_activity', 'HealthFitness_K-2', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about handwashing & hygiene habits.', '{"role":"wrapup","topic":"Handwashing & Hygiene Habits"}'::jsonb, 7),
  ('lesson_activity', 'HealthFitness_K-2', 'Assessment', 'Can the student answer the Practice question correctly and complete the Apply challenge as described?', '{"role":"assessment","topic":"Handwashing & Hygiene Habits"}'::jsonb, 8),
  ('lesson_activity', 'HealthFitness_3-5', 'Lesson Objective', 'Students will be able to explain and apply the core idea behind "MyPlate Food Groups & Balanced Meals."', '{"role":"objective","topic":"MyPlate Food Groups & Balanced Meals"}'::jsonb, 0),
  ('lesson_activity', 'HealthFitness_3-5', 'Materials Needed', 'Paper, pencil, and whatever the Apply challenge below calls for (a household item, a device, or internet access).', '{"role":"material","topic":"MyPlate Food Groups & Balanced Meals"}'::jsonb, 1),
  ('lesson_activity', 'HealthFitness_3-5', 'Warm-Up', 'Open class by asking students what they already know about myplate food groups & balanced meals, then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"MyPlate Food Groups & Balanced Meals"}'::jsonb, 2),
  ('lesson_activity', 'HealthFitness_3-5', 'Balanced Plates', 'Healthy bodies need foods from all 5 MyPlate groups: Fruits, Vegetables, Grains, Protein, and Dairy. Aim to make half your plate fruits and vegetables.', '{"role":"concept","topic":"MyPlate Food Groups & Balanced Meals"}'::jsonb, 3),
  ('lesson_activity', 'HealthFitness_3-5', 'Building a Healthy Plate', 'Timestamp 1:20 — "Whole grains give you long-lasting energy, while protein builds strong muscles."', '{"role":"watch","topic":"MyPlate Food Groups & Balanced Meals"}'::jsonb, 4),
  ('lesson_activity', 'HealthFitness_3-5', 'Practice: Half the Plate', 'Q: Which two food groups should make up half of your dinner plate?
A: Fruits and vegetables.', '{"role":"practice","topic":"MyPlate Food Groups & Balanced Meals"}'::jsonb, 5),
  ('lesson_activity', 'HealthFitness_3-5', 'Mini-Project: Draw a Balanced Plate', 'Draw a dinner plate divided into sections and fill each part with foods you like from the 5 main food groups.', '{"role":"apply","topic":"MyPlate Food Groups & Balanced Meals"}'::jsonb, 6),
  ('lesson_activity', 'HealthFitness_3-5', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about myplate food groups & balanced meals.', '{"role":"wrapup","topic":"MyPlate Food Groups & Balanced Meals"}'::jsonb, 7),
  ('lesson_activity', 'HealthFitness_3-5', 'Assessment', 'Can the student answer the Practice question correctly and complete the Apply challenge as described?', '{"role":"assessment","topic":"MyPlate Food Groups & Balanced Meals"}'::jsonb, 8),
  ('lesson_activity', 'HealthFitness_6-8', 'Lesson Objective', 'Students will be able to explain and apply the core idea behind "Cardiovascular Health & Target Heart Rate."', '{"role":"objective","topic":"Cardiovascular Health & Target Heart Rate"}'::jsonb, 0),
  ('lesson_activity', 'HealthFitness_6-8', 'Materials Needed', 'Paper, pencil, and whatever the Apply challenge below calls for (a household item, a device, or internet access).', '{"role":"material","topic":"Cardiovascular Health & Target Heart Rate"}'::jsonb, 1),
  ('lesson_activity', 'HealthFitness_6-8', 'Warm-Up', 'Open class by asking students what they already know about cardiovascular health & target heart rate, then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"Cardiovascular Health & Target Heart Rate"}'::jsonb, 2),
  ('lesson_activity', 'HealthFitness_6-8', 'Heart Rate & Aerobic Exercise', 'Your heart is a muscle. Aerobic exercise (running, swimming, cycling) strengthens it. Resting Heart Rate drops as fitness improves; Target Heart Rate shows how fast your heart should beat during exercise.', '{"role":"concept","topic":"Cardiovascular Health & Target Heart Rate"}'::jsonb, 3),
  ('lesson_activity', 'HealthFitness_6-8', 'Finding Your Pulse', 'Timestamp 1:50 — "Count your radial pulse beats on your wrist for 10 seconds and multiply by 6."', '{"role":"watch","topic":"Cardiovascular Health & Target Heart Rate"}'::jsonb, 4),
  ('lesson_activity', 'HealthFitness_6-8', 'Practice: Calculate BPM', 'Q: If you count 12 heartbeats in 10 seconds while resting, what is your heart rate in BPM?
A: 72 BPM.', '{"role":"practice","topic":"Cardiovascular Health & Target Heart Rate"}'::jsonb, 5),
  ('lesson_activity', 'HealthFitness_6-8', 'Mini-Project: Before & After Pulse', 'Measure and record your resting heart rate. Do 30 jumping jacks, measure your heart rate again immediately, and compare the two numbers.', '{"role":"apply","topic":"Cardiovascular Health & Target Heart Rate"}'::jsonb, 6),
  ('lesson_activity', 'HealthFitness_6-8', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about cardiovascular health & target heart rate.', '{"role":"wrapup","topic":"Cardiovascular Health & Target Heart Rate"}'::jsonb, 7),
  ('lesson_activity', 'HealthFitness_6-8', 'Assessment', 'Can the student answer the Practice question correctly and complete the Apply challenge as described?', '{"role":"assessment","topic":"Cardiovascular Health & Target Heart Rate"}'::jsonb, 8),
  ('lesson_activity', 'HealthFitness_9-12', 'Lesson Objective', 'Students will be able to explain and apply the core idea behind "Energy Balance & Macronutrient Calculations."', '{"role":"objective","topic":"Energy Balance & Macronutrient Calculations"}'::jsonb, 0),
  ('lesson_activity', 'HealthFitness_9-12', 'Materials Needed', 'Paper, pencil, and whatever the Apply challenge below calls for (a household item, a device, or internet access).', '{"role":"material","topic":"Energy Balance & Macronutrient Calculations"}'::jsonb, 1),
  ('lesson_activity', 'HealthFitness_9-12', 'Warm-Up', 'Open class by asking students what they already know about energy balance & macronutrient calculations, then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"Energy Balance & Macronutrient Calculations"}'::jsonb, 2),
  ('lesson_activity', 'HealthFitness_9-12', 'Macronutrients', 'Energy balance determines weight changes (Calories In − Calories Out). Carbohydrates and protein provide 4 kcal/g; fats provide 9 kcal/g.', '{"role":"concept","topic":"Energy Balance & Macronutrient Calculations"}'::jsonb, 3),
  ('lesson_activity', 'HealthFitness_9-12', 'Macronutrients Breakdown', 'Timestamp 2:10 — "Fats are energy-dense, offering more than double the calories per gram compared to carbs or protein."', '{"role":"watch","topic":"Energy Balance & Macronutrient Calculations"}'::jsonb, 4),
  ('lesson_activity', 'HealthFitness_9-12', 'Practice: Total the Calories', 'Q: How many total calories are in a snack with 10g Protein, 20g Carbs, and 5g Fat?
A: (10×4)+(20×4)+(5×9) = 165 kcal.', '{"role":"practice","topic":"Energy Balance & Macronutrient Calculations"}'::jsonb, 5),
  ('lesson_activity', 'HealthFitness_9-12', 'Mini-Project: Read a Nutrition Label', 'Choose a packaged food item. Read its nutrition label and calculate what percentage of its total calories comes from fats versus carbohydrates.', '{"role":"apply","topic":"Energy Balance & Macronutrient Calculations"}'::jsonb, 6),
  ('lesson_activity', 'HealthFitness_9-12', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about energy balance & macronutrient calculations.', '{"role":"wrapup","topic":"Energy Balance & Macronutrient Calculations"}'::jsonb, 7),
  ('lesson_activity', 'HealthFitness_9-12', 'Assessment', 'Can the student answer the Practice question correctly and complete the Apply challenge as described?', '{"role":"assessment","topic":"Energy Balance & Macronutrient Calculations"}'::jsonb, 8),
  ('lesson_activity', 'BusinessFinance_K-2', 'Lesson Objective', 'Students will be able to explain and apply the core idea behind "Needs vs. Wants."', '{"role":"objective","topic":"Needs vs. Wants"}'::jsonb, 0),
  ('lesson_activity', 'BusinessFinance_K-2', 'Materials Needed', 'Paper, pencil, and whatever the Apply challenge below calls for (a household item, a device, or internet access).', '{"role":"material","topic":"Needs vs. Wants"}'::jsonb, 1),
  ('lesson_activity', 'BusinessFinance_K-2', 'Warm-Up', 'Open class by asking students what they already know about needs vs. wants, then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"Needs vs. Wants"}'::jsonb, 2),
  ('lesson_activity', 'BusinessFinance_K-2', 'Needs & Wants', 'A need is something required to survive and stay healthy (food, water, shelter, warm clothes). A want is something nice to have but not required (toys, candy, video games).', '{"role":"concept","topic":"Needs vs. Wants"}'::jsonb, 3),
  ('lesson_activity', 'BusinessFinance_K-2', 'The Needs and Wants Song', 'Timestamp 0:50 — "We buy our needs first, and save money left over for our wants."', '{"role":"watch","topic":"Needs vs. Wants"}'::jsonb, 4),
  ('lesson_activity', 'BusinessFinance_K-2', 'Practice: Need or Want?', 'Q: Is a winter coat a Need or a Want?
A: Need.', '{"role":"practice","topic":"Needs vs. Wants"}'::jsonb, 5),
  ('lesson_activity', 'BusinessFinance_K-2', 'Mini-Project: Needs & Wants Drawing', 'Look around your room. Draw 2 things that are Needs and 2 things that are Wants, labeling each one.', '{"role":"apply","topic":"Needs vs. Wants"}'::jsonb, 6),
  ('lesson_activity', 'BusinessFinance_K-2', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about needs vs. wants.', '{"role":"wrapup","topic":"Needs vs. Wants"}'::jsonb, 7),
  ('lesson_activity', 'BusinessFinance_K-2', 'Assessment', 'Can the student answer the Practice question correctly and complete the Apply challenge as described?', '{"role":"assessment","topic":"Needs vs. Wants"}'::jsonb, 8),
  ('lesson_activity', 'BusinessFinance_3-5', 'Lesson Objective', 'Students will be able to explain and apply the core idea behind "Earn, Save, Spend & Give."', '{"role":"objective","topic":"Earn, Save, Spend & Give"}'::jsonb, 0),
  ('lesson_activity', 'BusinessFinance_3-5', 'Materials Needed', 'Paper, pencil, and whatever the Apply challenge below calls for (a household item, a device, or internet access).', '{"role":"material","topic":"Earn, Save, Spend & Give"}'::jsonb, 1),
  ('lesson_activity', 'BusinessFinance_3-5', 'Warm-Up', 'Open class by asking students what they already know about earn, save, spend & give, then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"Earn, Save, Spend & Give"}'::jsonb, 2),
  ('lesson_activity', 'BusinessFinance_3-5', 'The 4 Money Jars', 'Money earned can be split into four jars: Spend (everyday expenses), Save (bigger future goals), Give (helping others), Invest (growing money over time).', '{"role":"concept","topic":"Earn, Save, Spend & Give"}'::jsonb, 3),
  ('lesson_activity', 'BusinessFinance_3-5', 'The 4 Money Jars System', 'Timestamp 1:15 — "Putting even $1 out of every $10 into your savings jar builds a strong habit."', '{"role":"watch","topic":"Earn, Save, Spend & Give"}'::jsonb, 4),
  ('lesson_activity', 'BusinessFinance_3-5', 'Practice: Save 20%', 'Q: If you earn $10 doing yard work and put 20% into your Save jar, how much goes into the Save jar?
A: $2.00.', '{"role":"practice","topic":"Earn, Save, Spend & Give"}'::jsonb, 5),
  ('lesson_activity', 'BusinessFinance_3-5', 'Mini-Project: Savings Goal Tracker', 'Create a savings goal tracker on paper for an item you want to buy, showing how much you need to save each week to buy it in 4 weeks.', '{"role":"apply","topic":"Earn, Save, Spend & Give"}'::jsonb, 6),
  ('lesson_activity', 'BusinessFinance_3-5', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about earn, save, spend & give.', '{"role":"wrapup","topic":"Earn, Save, Spend & Give"}'::jsonb, 7),
  ('lesson_activity', 'BusinessFinance_3-5', 'Assessment', 'Can the student answer the Practice question correctly and complete the Apply challenge as described?', '{"role":"assessment","topic":"Earn, Save, Spend & Give"}'::jsonb, 8),
  ('lesson_activity', 'BusinessFinance_6-8', 'Lesson Objective', 'Students will be able to explain and apply the core idea behind "Budgeting & Fixed vs. Variable Costs."', '{"role":"objective","topic":"Budgeting & Fixed vs. Variable Costs"}'::jsonb, 0),
  ('lesson_activity', 'BusinessFinance_6-8', 'Materials Needed', 'Paper, pencil, and whatever the Apply challenge below calls for (a household item, a device, or internet access).', '{"role":"material","topic":"Budgeting & Fixed vs. Variable Costs"}'::jsonb, 1),
  ('lesson_activity', 'BusinessFinance_6-8', 'Warm-Up', 'Open class by asking students what they already know about budgeting & fixed vs. variable costs, then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"Budgeting & Fixed vs. Variable Costs"}'::jsonb, 2),
  ('lesson_activity', 'BusinessFinance_6-8', 'Fixed vs. Variable Expenses', 'A budget tracks income and expenses. Fixed expenses stay the same every month (rent, subscriptions). Variable expenses change based on choices or usage (groceries, entertainment).', '{"role":"concept","topic":"Budgeting & Fixed vs. Variable Costs"}'::jsonb, 3),
  ('lesson_activity', 'BusinessFinance_6-8', 'Building Your First Budget', 'Timestamp 2:05 — "Always list fixed expenses first so you know your essential costs are covered."', '{"role":"watch","topic":"Budgeting & Fixed vs. Variable Costs"}'::jsonb, 4),
  ('lesson_activity', 'BusinessFinance_6-8', 'Practice: Fixed or Variable?', 'Q: Is a $15 monthly streaming membership a fixed or variable expense?
A: Fixed expense.', '{"role":"practice","topic":"Budgeting & Fixed vs. Variable Costs"}'::jsonb, 5),
  ('lesson_activity', 'BusinessFinance_6-8', 'Mini-Project: Build a Mock Budget', 'Build a mock monthly budget for a student who earns $100/month from tutoring. Allocate income across fixed subscriptions, variable spending, and savings.', '{"role":"apply","topic":"Budgeting & Fixed vs. Variable Costs"}'::jsonb, 6),
  ('lesson_activity', 'BusinessFinance_6-8', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about budgeting & fixed vs. variable costs.', '{"role":"wrapup","topic":"Budgeting & Fixed vs. Variable Costs"}'::jsonb, 7),
  ('lesson_activity', 'BusinessFinance_6-8', 'Assessment', 'Can the student answer the Practice question correctly and complete the Apply challenge as described?', '{"role":"assessment","topic":"Budgeting & Fixed vs. Variable Costs"}'::jsonb, 8),
  ('lesson_activity', 'BusinessFinance_9-12', 'Lesson Objective', 'Students will be able to explain and apply the core idea behind "The Power of Compound Interest."', '{"role":"objective","topic":"The Power of Compound Interest"}'::jsonb, 0),
  ('lesson_activity', 'BusinessFinance_9-12', 'Materials Needed', 'Paper, pencil, and whatever the Apply challenge below calls for (a household item, a device, or internet access).', '{"role":"material","topic":"The Power of Compound Interest"}'::jsonb, 1),
  ('lesson_activity', 'BusinessFinance_9-12', 'Warm-Up', 'Open class by asking students what they already know about the power of compound interest, then preview today''s Learn section as the answer.', '{"role":"warmup","topic":"The Power of Compound Interest"}'::jsonb, 2),
  ('lesson_activity', 'BusinessFinance_9-12', 'Compound Interest', 'Simple interest grows only on the principal. Compound interest grows on both the principal and previously earned interest — A = P(1 + r/n)^(nt). Starting early gives time exponential leverage.', '{"role":"concept","topic":"The Power of Compound Interest"}'::jsonb, 3),
  ('lesson_activity', 'BusinessFinance_9-12', 'Visualizing Exponential Wealth Growth', 'Timestamp 3:00 — "Notice how the growth curve steepens after year 10 thanks to compounding."', '{"role":"watch","topic":"The Power of Compound Interest"}'::jsonb, 4),
  ('lesson_activity', 'BusinessFinance_9-12', 'Practice: Compound Two Years', 'Q: If you invest $1,000 at 10% annual interest compounded yearly, how much do you have after 2 years?
A: Year 1 = $1,100; Year 2 = $1,210.', '{"role":"practice","topic":"The Power of Compound Interest"}'::jsonb, 5),
  ('lesson_activity', 'BusinessFinance_9-12', 'Mini-Project: Compare Starting Ages', 'Use an online compound interest calculator to compute the difference at age 60 between investing $100/month starting at age 20 versus starting at age 30 (7% average annual return).', '{"role":"apply","topic":"The Power of Compound Interest"}'::jsonb, 6),
  ('lesson_activity', 'BusinessFinance_9-12', 'Wrap-Up & Reflection', 'Have a few students share what they made or found for the Apply challenge and explain one thing they learned about the power of compound interest.', '{"role":"wrapup","topic":"The Power of Compound Interest"}'::jsonb, 7),
  ('lesson_activity', 'BusinessFinance_9-12', 'Assessment', 'Can the student answer the Practice question correctly and complete the Apply challenge as described?', '{"role":"assessment","topic":"The Power of Compound Interest"}'::jsonb, 8)
on conflict do nothing;

-- ── Enrich 6 demonstration class_topic rows with Learn/Practice/Apply ──
-- One per built subject — the rest of each subject's topics are ready
-- for the same treatment whenever content is added for them.

update public.app_content
set meta = meta || '{"learn":[{"heading":"What is Counting On?","body":"Addition means combining groups. \"Counting on\" is a shortcut: instead of counting every object from 1, start at the bigger number and count up. For 5 + 3, start at 5, then count \"6, 7, 8.\""},{"heading":"Why It Works","body":"The last number you say when counting a group always names how many are in it — that''s the cardinality principle. Starting from the bigger number just skips counting the smaller group one-by-one."}],"practice":[{"question":"What is 6 + 3? Start at 6 and count on 3 steps.","options":["8","9","10","7"],"answerIndex":1,"explanation":"6, then count on 3: 7, 8, 9."},{"question":"If you count a pile of blocks and the last number you say is \"12,\" how many blocks are there?","options":["1","12","Depends on the color","You have to count twice"],"answerIndex":1,"explanation":"The last number counted names the total — that''s cardinality."}],"apply":{"prompt":"Grab 7 small objects (coins, blocks, or spoons). Add 2 more. Count on out loud to find the total, then take a photo of your group.","checklist":["Started with 7 objects","Added 2 more objects","Counted on out loud from 7","Said the total out loud"]}}'::jsonb
where type = 'class_topic' and key = 'NumbersAndOperations' and meta->>'topic_key' = 'counting';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Rhyming & Word Families","body":"Words rhyme when they end with the same sound — cat, hat, mat. Changing just the first letter creates a new word in the same \"word family.\""},{"heading":"Why It Matters","body":"Hearing and playing with sounds in words is one of the strongest early predictors of reading success — before kids ever sound out a letter, they need to hear how words are built."}],"practice":[{"question":"Which word rhymes with \"bug\"?","options":["Bag","Hug","Big","Bud"],"answerIndex":1,"explanation":"\"Hug\" ends with the same \"-ug\" sound as \"bug.\""},{"question":"\"Cat,\" \"hat,\" and \"mat\" all belong to the same...","options":["Color group","Word family","Number family","Shape"],"answerIndex":1,"explanation":"They share the \"-at\" ending, so swapping the first sound makes a new rhyming word."}],"apply":{"prompt":"Draw a picture of a cat wearing a hat sitting on a mat. Label all three rhyming words in your drawing.","checklist":["Drew a cat","Drew a hat","Drew a mat","Labeled all three words"]}}'::jsonb
where type = 'class_topic' and key = 'Reading' and meta->>'topic_key' = 'phonologicalAwareness';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Living or Non-Living?","body":"Living things need food, water, air, and room to grow — like plants, animals, and people. Non-living things do not eat, breathe, or grow on their own — like rocks, toys, and chairs."},{"heading":"Tricky Cases","body":"A toy robot can move on its own, but it doesn''t eat, grow, or need air — so it''s non-living. A seed looks still, but it drinks water and grows into a plant — so it''s living."}],"practice":[{"question":"Is a tree living or non-living?","options":["Living","Non-living"],"answerIndex":0,"explanation":"A tree drinks water, uses sunlight, and grows — that makes it living."},{"question":"Which of these is non-living?","options":["A dog","A rock","A flower","A person"],"answerIndex":1,"explanation":"A rock doesn''t eat, breathe, or grow."}],"apply":{"prompt":"Walk around your room or yard. Find 2 living things and 2 non-living things, and photograph or draw a checklist of them.","checklist":["Found 1st living thing","Found 2nd living thing","Found 1st non-living thing","Found 2nd non-living thing"]}}'::jsonb
where type = 'class_topic' and key = 'Biology' and meta->>'topic_key' = 'livingThings';

update public.app_content
set meta = meta || '{"learn":[{"heading":"River Valley Civilizations","body":"Early civilizations like Mesopotamia and Ancient Egypt grew up along major rivers — the Tigris, Euphrates, and Nile. River valleys provided fertile soil, fresh water, and easy transportation."},{"heading":"Why the Nile Mattered","body":"The Nile flooded predictably every year, depositing rich silt on its banks. That silt let ancient Egyptian farmers grow surplus food — freeing some people to become builders, priests, and rulers instead of full-time farmers."}],"practice":[{"question":"Why was the Nile River essential to ancient Egyptian civilization?","options":["It never flooded","It provided fertile soil for farming and a trade route","It was too dangerous to settle near","It froze every winter"],"answerIndex":1,"explanation":"Annual flooding deposited fertile silt, and the river also worked as a highway for trade."},{"question":"What do Mesopotamia, Egypt, and the Indus Valley civilizations have in common?","options":["They were all islands","They all formed near major rivers","They had no agriculture","They were all in the same country"],"answerIndex":1,"explanation":"All three grew up in river valleys, which supplied water, fertile soil, and transportation."}],"apply":{"prompt":"Find a world map. Identify 2 modern countries that sit along historical river valleys and list 1 natural advantage that location still provides today.","checklist":["Found country #1 on a river valley","Found country #2 on a river valley","Wrote 1 modern advantage for each"]}}'::jsonb
where type = 'class_topic' and key = 'History' and meta->>'topic_key' = 'ancientCivilizations';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Lines Make Everything","body":"Every drawing starts with lines — straight, curved, thick, thin, zigzag. Different lines create different feelings: straight lines feel calm and orderly, wavy lines feel playful or flowing."},{"heading":"Shapes From Lines","body":"Combine simple shapes — circles, squares, triangles — to build more complex pictures. A robot might be a square body, a circle head, and rectangle arms."}],"practice":[{"question":"Which kind of line usually feels calm and orderly?","options":["A wavy line","A straight line","A zigzag line","A scribble"],"answerIndex":1,"explanation":"Straight lines tend to feel neat and steady; wavy and zigzag lines feel more playful or energetic."},{"question":"If you wanted to draw a simple house, which shapes would you combine?","options":["Only circles","A square/rectangle and a triangle","Only zigzag lines","Only dots"],"answerIndex":1,"explanation":"A rectangle for the walls and a triangle for the roof is the classic combination."}],"apply":{"prompt":"Draw a picture (a house, animal, or robot) using only circles, squares, triangles, and rectangles. Then trace over your favorite line in a different color.","checklist":["Used at least 3 different shapes","Drew at least 2 different kinds of lines","Colored or traced a favorite line"]}}'::jsonb
where type = 'class_topic' and key = 'VisualArt' and meta->>'topic_key' = 'drawingIllustration';

update public.app_content
set meta = meta || '{"learn":[{"heading":"Wash, Separate, Cook, Chill","body":"The four keys to food safety: wash your hands and surfaces often, keep raw meat separate from other foods, cook food to a safe temperature, and chill leftovers quickly."},{"heading":"Measuring Matters Too","body":"Safe cooking also means measuring correctly — liquid measuring cups (clear, with a spout) for liquids, and dry measuring cups (leveled off flat with a knife) for dry ingredients like flour or sugar."}],"practice":[{"question":"Which tool should you use to measure 1/2 cup of milk?","options":["A dry measuring cup","A clear liquid measuring cup","A tablespoon","Your hands"],"answerIndex":1,"explanation":"Liquids get measured in a clear cup with a spout so you can check the line at eye level."},{"question":"Why should raw meat be kept separate from other foods while cooking?","options":["It smells bad","To keep germs from spreading to other food (cross-contamination)","It cooks faster alone","It is more expensive"],"answerIndex":1,"explanation":"Raw meat can carry germs that spread to other foods if they touch — that''s called cross-contamination."}],"apply":{"prompt":"Find a measuring cup or spoon at home. Measure 1 cup of water and pour it into a clear glass, photographing your measurement at eye level.","checklist":["Found a measuring cup","Measured exactly 1 cup","Checked the level at eye height","Took a photo"]}}'::jsonb
where type = 'class_topic' and key = 'NutritionAndFood' and meta->>'topic_key' = 'foodSafety';
